let today = '';
let tasks = [];
let sessions = [];
let rules = [];
let revs = new Map();
let busy = false;
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const WINDOW = 14;

function $(id) { return document.getElementById(id); }
function say(text, bad) {
  const s = $('status');
  s.textContent = text;
  s.className = bad ? 'status bad' : 'status';
}
function addDays(str, n) {
  const [y, m, d] = str.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}
function weekdayOf(str) {
  const [y, m, d] = str.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}
function pretty(str) {
  const [y, m, d] = str.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString('en', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' });
}
function revKey(c, id) { return c + '/' + id; }
function rev(c, id) { return revs.get(revKey(c, id)) || 1; }

async function load() {
  const r = await tessera.call('data.read', {});
  const d = r.data;
  tasks = Array.isArray(d.tasks) ? d.tasks : [];
  sessions = Array.isArray(d.sessions) ? d.sessions : [];
  rules = Array.isArray(d.rules) ? d.rules : [];
  revs = new Map();
  for (const [c, recs] of Object.entries(r.revisions || {})) {
    for (const [id, n] of Object.entries(recs)) revs.set(revKey(c, id), n);
  }
}

function blockedSet(list) {
  const s = new Set();
  for (const r of list) s.add(Number(r.weekday));
  return s;
}
function allowedDays(blocked) {
  const out = [];
  for (let i = 0; i < WINDOW; i++) {
    const day = addDays(today, i);
    if (!blocked.has(weekdayOf(day))) out.push(day);
  }
  return out;
}
function loadCounts(list) {
  const m = new Map();
  for (const s of list) m.set(s.date, (m.get(s.date) || 0) + 1);
  return m;
}
function pickDays(allowed, counts, n) {
  const len = allowed.length;
  const chosen = [];
  for (let k = 0; k < n; k++) {
    const target = Math.floor((k + 0.5) * len / n);
    let best = null;
    let bestScore = Infinity;
    for (let o = -1; o <= 1; o++) {
      const idx = target + o;
      if (idx < 0 || idx >= len) continue;
      const day = allowed[idx];
      if (chosen.includes(day)) continue;
      const score = (counts.get(day) || 0) * 10 + Math.abs(o);
      if (score < bestScore) { bestScore = score; best = day; }
    }
    if (best === null) {
      for (const day of allowed) if (!chosen.includes(day)) { best = day; break; }
    }
    if (best !== null) chosen.push(best);
  }
  return chosen;
}

async function run(fn) {
  if (busy) return;
  busy = true;
  $('task-add').disabled = true;
  $('rule-add').disabled = true;
  try { await fn(); } catch (e) {
    say('That didn\'t work, nothing was changed. Please try again.', true);
    try { await load(); } catch (e2) { /* keep the screen as is */ }
  }
  busy = false;
  $('task-add').disabled = false;
  $('rule-add').disabled = false;
  render();
}

async function addTask() {
  const input = $('task-name');
  const name = input.value.trim();
  $('task-error').textContent = '';
  if (!name) {
    $('task-error').textContent = 'Type a topic name first.';
    input.focus();
    return;
  }
  await run(async () => {
    const blocked = blockedSet(rules);
    const allowed = allowedDays(blocked);
    if (allowed.length === 0) {
      $('task-error').textContent = 'Every weekday is ruled out, so there is no day to study. Remove a rule first.';
      return;
    }
    const days = pickDays(allowed, loadCounts(sessions), Math.min(3, allowed.length));
    const res = await tessera.call('data.patch', { operations: [{ op: 'add', collection: 'tasks', record: { name } }] });
    const [taskId] = res.addedIds;
    const ops = [];
    for (const day of days) ops.push({ op: 'add', collection: 'sessions', record: { taskId, date: day } });
    await tessera.call('data.patch', { operations: ops });
    await load();
    input.value = '';
    say('Added "' + name + '" with ' + days.length + (days.length === 1 ? ' session.' : ' sessions.'));
  });
  input.focus();
}

async function addRule() {
  const day = Number($('rule-day').value);
  $('rule-error').textContent = '';
  await run(async () => {
    const blocked = blockedSet(rules);
    if (blocked.has(day)) {
      $('rule-error').textContent = 'You already have a rule for ' + DAYS[day] + '.';
      return;
    }
    const next = new Set(blocked);
    next.add(day);
    const allowed = allowedDays(next);
    if (allowed.length === 0) {
      $('rule-error').textContent = 'That would leave no day to study.';
      return;
    }
    const affected = sessions.filter(s => weekdayOf(s.date) === day).sort((a, b) => a.date.localeCompare(b.date));
    const kept = sessions.filter(s => weekdayOf(s.date) !== day);
    const counts = loadCounts(kept);
    const taskDates = new Map();
    const remaining = new Map();
    for (const s of kept) {
      if (!taskDates.has(s.taskId)) taskDates.set(s.taskId, new Set());
      taskDates.get(s.taskId).add(s.date);
      remaining.set(s.taskId, (remaining.get(s.taskId) || 0) + 1);
    }
    const ops = [{ op: 'add', collection: 'rules', record: { weekday: day } }];
    let moved = 0;
    for (const s of affected) {
      const has = taskDates.get(s.taskId) || new Set();
      let cands = allowed.filter(d => !has.has(d));
      if (cands.length === 0) {
        if ((remaining.get(s.taskId) || 0) > 0) {
          ops.push({ op: 'remove', collection: 'sessions', id: s.id, revisionCount: rev('sessions', s.id) });
          continue;
        }
        cands = allowed;
      }
      let best = cands[0];
      for (const d of cands) if ((counts.get(d) || 0) < (counts.get(best) || 0)) best = d;
      counts.set(best, (counts.get(best) || 0) + 1);
      has.add(best);
      taskDates.set(s.taskId, has);
      remaining.set(s.taskId, (remaining.get(s.taskId) || 0) + 1);
      ops.push({ op: 'replace', collection: 'sessions', id: s.id, revisionCount: rev('sessions', s.id), fields: { date: best } });
      moved++;
    }
    await tessera.call('data.patch', { operations: ops });
    await load();
    say('No studying on ' + DAYS[day] + 's now. ' + (affected.length === 0 ? 'No sessions had to move.' : affected.length + (affected.length === 1 ? ' session was' : ' sessions were') + ' moved to other days.'));
  });
  $('rule-add').focus();
}

async function removeRule(rule) {
  await run(async () => {
    await tessera.call('data.patch', { operations: [{ op: 'remove', collection: 'rules', id: rule.id, revisionCount: rev('rules', rule.id) }] });
    await load();
    say('Rule removed. Existing sessions stay where they are; new topics may use ' + DAYS[Number(rule.weekday)] + 's again.');
  });
  $('rule-day').focus();
}

async function removeTask(task) {
  await run(async () => {
    const ops = [];
    for (const s of sessions) if (s.taskId === task.id) ops.push({ op: 'remove', collection: 'sessions', id: s.id, revisionCount: rev('sessions', s.id) });
    ops.push({ op: 'remove', collection: 'tasks', id: task.id, revisionCount: rev('tasks', task.id) });
    await tessera.call('data.patch', { operations: ops });
    await load();
    say('Removed "' + task.name + '" and its sessions.');
  });
  $('task-name').focus();
}

function mk(tag, text, cls) {
  const e = document.createElement(tag);
  if (text !== undefined) e.textContent = text;
  if (cls) e.className = cls;
  return e;
}

function render() {
  $('exam-day').textContent = today ? 'Today is ' + pretty(today) + '. Exam day: ' + pretty(addDays(today, WINDOW)) + '.' : '';

  const rl = $('rules');
  rl.replaceChildren();
  const sortedRules = rules.slice().sort((a, b) => Number(a.weekday) - Number(b.weekday));
  for (const r of sortedRules) {
    const li = mk('li');
    li.setAttribute('data-hook', 'rule');
    li.appendChild(mk('span', 'No studying on ' + DAYS[Number(r.weekday)] + 's'));
    const b = mk('button', 'Remove rule', 'secondary');
    b.type = 'button';
    b.setAttribute('data-hook', 'rule-remove');
    b.setAttribute('aria-label', 'Remove rule: no studying on ' + DAYS[Number(r.weekday)] + 's');
    b.addEventListener('click', () => removeRule(r));
    li.appendChild(b);
    rl.appendChild(li);
  }

  const byId = new Map();
  for (const t of tasks) byId.set(t.id, t);

  const tl = $('topics');
  tl.replaceChildren();
  for (const t of tasks) {
    const n = sessions.filter(s => s.taskId === t.id).length;
    const li = mk('li');
    const w = mk('span', t.name);
    li.appendChild(w);
    li.appendChild(mk('span', n + (n === 1 ? ' session' : ' sessions'), 'muted'));
    const b = mk('button', 'Remove', 'secondary');
    b.type = 'button';
    b.setAttribute('aria-label', 'Remove topic ' + t.name);
    b.addEventListener('click', () => removeTask(t));
    li.appendChild(b);
    tl.appendChild(li);
  }
  $('topics-empty').hidden = tasks.length > 0;

  const sl = $('sessions');
  sl.replaceChildren();
  const sorted = sessions.filter(s => byId.has(s.taskId)).sort((a, b) => a.date.localeCompare(b.date));
  for (const s of sorted) {
    const li = mk('li');
    li.setAttribute('data-hook', 'session');
    const wrap = mk('span', undefined, 'when');
    const t = document.createElement('time');
    t.setAttribute('datetime', s.date);
    t.textContent = pretty(s.date);
    wrap.appendChild(t);
    const nm = mk('span', byId.get(s.taskId).name);
    nm.setAttribute('data-hook', 'session-task');
    wrap.appendChild(nm);
    li.appendChild(wrap);
    li.appendChild(mk('span', 'Evening', 'muted'));
    sl.appendChild(li);
  }
  $('sessions-empty').hidden = sorted.length > 0;
}

$('task-add').addEventListener('click', addTask);
$('task-name').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); addTask(); } });
$('rule-add').addEventListener('click', addRule);

(async () => {
  try {
    const c = await tessera.call('clock.now', {});
    today = c.date;
    await load();
  } catch (e) {
    say('Could not load your plan. Please reopen the tool.', true);
  }
  render();
})();

