const notes = document.getElementById('notes');
const makeBtn = document.getElementById('make');
const statusEl = document.getElementById('status');
const listEl = document.getElementById('list');
const emptyEl = document.getElementById('empty');
const countEl = document.getElementById('count');

function say(text, kind) {
  statusEl.textContent = text;
  statusEl.className = kind || '';
}

async function load() {
  const res = await tessera.call('data.read', {});
  const cards = Array.isArray(res.data.cards) ? res.data.cards : [];
  const revs = new Map();
  for (const [id, rev] of Object.entries(res.revisions.cards || {})) revs.set(id, rev);
  render(cards, revs);
}

function render(cards, revs) {
  listEl.textContent = '';
  emptyEl.hidden = cards.length > 0;
  countEl.textContent = cards.length ? '(' + cards.length + ')' : '';
  for (const card of cards) {
    const li = document.createElement('li');
    li.setAttribute('data-hook', 'card');
    const box = document.createElement('div');
    box.className = 'txt';
    const f = document.createElement('div');
    f.className = 'front';
    f.setAttribute('data-hook', 'card-front');
    f.textContent = card.front;
    const b = document.createElement('div');
    b.className = 'back';
    b.setAttribute('data-hook', 'card-back');
    b.textContent = card.back;
    box.appendChild(f);
    box.appendChild(b);
    const del = document.createElement('button');
    del.type = 'button';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete card: ' + card.front);
    del.addEventListener('click', async () => {
      try {
        await tessera.call('data.patch', { operations: [{ op: 'remove', collection: 'cards', id: card.id, revisionCount: revs.get(card.id) }] });
        await load();
        say('Card deleted.', 'ok');
      } catch (e) {
        say('The card could not be deleted. Please try again.', 'err');
      }
    });
    li.appendChild(box);
    li.appendChild(del);
    listEl.appendChild(li);
  }
}

function parse(text) {
  const out = [];
  for (const line of text.split(/\r?\n/)) {
    const i = line.indexOf(':');
    if (i < 0) continue;
    const front = line.slice(0, i).trim();
    const back = line.slice(i + 1).trim();
    if (front && back) out.push({ front, back });
  }
  return out;
}

makeBtn.addEventListener('click', async () => {
  const found = parse(notes.value);
  if (!found.length) {
    say('No cards made. Write each card as "front: back", one per line.', 'err');
    return;
  }
  try {
    await tessera.call('data.patch', { operations: found.map((r) => ({ op: 'add', collection: 'cards', record: r })) });
    notes.value = '';
    await load();
    say(found.length === 1 ? '1 card made and saved.' : found.length + ' cards made and saved.', 'ok');
  } catch (e) {
    say('The cards could not be saved. Your notes are still here; please try again.', 'err');
  }
});

load().catch(() => say('The cards could not be loaded.', 'err'));
